// ─── Interface ────────────────────────────────────────────────────────────────

export type ObatStatus = 'Aktif' | 'Tidak Aktif' | 'Terbatas';

export interface ObatItem {
  id: string;                  // URL slug, digunakan di routing
  uuid: string;                // UUID internal (tidak ditampilkan)
  namaGenerik: string;
  namaLatin: string | null;
  kategoriSlug: ObatKategoriSlug;
  subKategori: ObatSubKategori;
  golonganObat: string;
  bentukSediaan: string;
  kandunganAktif: string;
  konsentrasi: string;
  spektrumKerja: string;
  indikasi: string;
  kontraindikasi: string;
  efekSamping: string;
  withdrawalTime: string;
  masaSimpan: string;
  caraPenyimpanan: string;
  catatan: string | null;
  status: ObatStatus;
  dataLengkap: boolean;
  createdAt: string;          // ISO-style date: when this record was first added to the database
  updatedAt: string;
}

