// ─── Helpers ──────────────────────────────────────────────────────────────────

export function getObatList(): ObatItem[] {
  return OBAT_DB;
}

export function getObatByKategori(slug: ObatKategoriSlug): ObatItem[] {
  return OBAT_DB.filter(o => o.kategoriSlug === slug);
}

export function getObatById(id: string): ObatItem | undefined {
  return OBAT_DB.find(o => o.id === id);
}

/** Lookup by internal UUID — used by PKO-004 (Produk Komersial Obat Admin) to resolve masterObatUuid. */
export function getObatByUuid(uuid: string): ObatItem | undefined {
  return OBAT_DB.find(o => o.uuid === uuid);
}

export function computeObatRingkasan(slug: ObatKategoriSlug) {
  const items = getObatByKategori(slug);
  const dataLengkap = items.filter(i => i.dataLengkap).length;
  const terakhirUpdate = items.map(i => i.updatedAt).sort((a, b) => b.localeCompare(a))[0] ?? '—';
  return { totalReferensi: items.length, dataLengkap, terakhirUpdate };
}
